'use strict'

import { TILE_WIDTH, TILE_HEIGHT } from '../constant'
import { overlaps } from '../utils/box'

// Tile hitboxes are convex polygons (a subset of the 8 points of the tile, in clockwise
// order), so an exact separating axis test is enough: no polygon union needed.

function project (points, axis) {
  let min = Infinity
  let max = -Infinity
  for (const [x, y] of points) {
    const value = x * axis[0] + y * axis[1]
    min = Math.min(min, value)
    max = Math.max(max, value)
  }

  return { min, max }
}

function area (points) {
  let sum = 0
  for (let i = 0; i < points.length; i++) {
    const [x1, y1] = points[i]
    const [x2, y2] = points[(i + 1) % points.length]
    sum += x1 * y2 - x2 * y1
  }

  return Math.abs(sum) / 2
}

// Touching edges are not an overlap, so Link can walk flush against a wall
export function rectIntersectsPolygon (rect, points) {
  if (points.length < 3 || area(points) === 0) {
    return false
  }

  const corners = [
    [rect.x, rect.y],
    [rect.x + rect.width, rect.y],
    [rect.x + rect.width, rect.y + rect.height],
    [rect.x, rect.y + rect.height]
  ]
  const axes = [[1, 0], [0, 1]]
  for (let i = 0; i < points.length; i++) {
    const [x1, y1] = points[i]
    const [x2, y2] = points[(i + 1) % points.length]
    if (x1 !== x2 || y1 !== y2) {
      axes.push([y1 - y2, x2 - x1])
    }
  }

  for (const axis of axes) {
    const a = project(corners, axis)
    const b = project(points, axis)
    if (a.max <= b.min || b.max <= a.min) {
      return false
    }
  }

  return true
}

// The tiles under the rectangle; outside the map there is none (leaving the screen is handled by the map
// transitions)
function * tilesUnder (map, rect) {
  const firstColumn = Math.floor((rect.x - map.x) / TILE_WIDTH)
  const lastColumn = Math.ceil((rect.x + rect.width - map.x) / TILE_WIDTH) - 1
  const firstLine = Math.floor((rect.y - map.y) / TILE_HEIGHT)
  const lastLine = Math.ceil((rect.y + rect.height - map.y) / TILE_HEIGHT) - 1
  for (let column = firstColumn; column <= lastColumn; column++) {
    for (let line = firstLine; line <= lastLine; line++) {
      const tile = map.getTile(column, line)
      if (tile) {
        yield tile
      }
    }
  }
}

// As in the ROM: blocked by the quarters of the tiles (8 NES pixels), never by a slope (Link, and the probes of
// the walkers). Nothing blocks inside the free box (the ladder over the water)
export function isBlockedByQuarters (map, rect, free) {
  const isFree = quarter => free && quarter.x >= free.x && quarter.y >= free.y && quarter.x + quarter.width <= free.x + free.width && quarter.y + quarter.height <= free.y + free.height
  for (const tile of tilesUnder(map, rect)) {
    if (tile.blockQuarters.some(quarter => overlaps(rect, quarter) && !isFree(quarter))) {
      return true
    }
  }

  return false
}

// The enemies: blocked by the polygons of the tiles
export function isBlocked (map, rect) {
  const firstColumn = Math.floor((rect.x - map.x) / TILE_WIDTH)
  const lastColumn = Math.ceil((rect.x + rect.width - map.x) / TILE_WIDTH) - 1
  const firstLine = Math.floor((rect.y - map.y) / TILE_HEIGHT)
  const lastLine = Math.ceil((rect.y + rect.height - map.y) / TILE_HEIGHT) - 1
  for (let column = firstColumn; column <= lastColumn; column++) {
    for (let line = firstLine; line <= lastLine; line++) {
      const tile = map.getTile(column, line)
      if (tile && rectIntersectsPolygon(rect, tile.blockPoints)) {
        return true
      }
    }
  }

  return false
}
