'use strict'

import { CaveEntrance, CaveExit, CaveStairsDown, CaveStairsUp, LevelExit, MapDrag } from '../model/transition'
import { TRANSITION_CAVE_ENTRANCE, TRANSITION_CAVE_EXIT, TRANSITION_CAVE_STAIRS_DOWN, TRANSITION_CAVE_STAIRS_UP, TRANSITION_LEVEL_EXIT, TRANSITION_MAP_DRAG } from '../constant'

export default {
  transitions: {
    [TRANSITION_CAVE_ENTRANCE]: new CaveEntrance(),
    [TRANSITION_CAVE_EXIT]: new CaveExit(),
    [TRANSITION_CAVE_STAIRS_DOWN]: new CaveStairsDown(),
    [TRANSITION_CAVE_STAIRS_UP]: new CaveStairsUp(),
    [TRANSITION_LEVEL_EXIT]: new LevelExit(),
    [TRANSITION_MAP_DRAG]: new MapDrag()
  },
  get: function (name) {
    return this.transitions[name]
  }
}
